CREATE SET TABLE MDP01_META.META_DATATYPE ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      datatype_id INTEGER NOT NULL,      datatype_name VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      teradata_type VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      category VARCHAR(20) CHARACTER SET LATIN NOT CASESPECIFIC,      requires_length CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N',      requires_precision CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N',      requires_scale CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N',      max_length INTEGER,      max_precision INTEGER,      beschreibung VARCHAR(500) CHARACTER SET LATIN NOT CASESPECIFIC,      beispiel VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC,      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( datatype_id )UNIQUE INDEX ( datatype_name );